from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
p=json.loads((ROOT/'qa'/'planet_delivery_check.json').read_text())
keys=['CYCLES_64','EEVEE_128']; labels={'CYCLES_64':'Cycles · 64 samples + OIDN','EEVEE_128':'EEVEE · 128 samples'}
data=[{'name':labels[k],'seconds':p['weighted_seconds_per_frame'][k],'minimum':min(x['seconds'] for x in p['measured'][k].values()),'maximum':max(x['seconds'] for x in p['measured'][k].values())} for k in keys]
rows=''.join('<tr><td>'+b+'</td>'+''.join('<td>'+f'{p["measured"][k][b]["seconds"]:.2f}'+'</td>' for k in ['CYCLES_512','CYCLES_64','EEVEE_128'])+'</tr>' for b in p['duration_weights_seconds'])
html='''<!doctype html><html lang="ro"><meta charset="utf-8"><style>
body{margin:0;font:15px/1.5 var(--font-sans,system-ui);color:var(--foreground)}h2{font-size:20px;line-height:1.3;margin:0 0 8px}.sub{color:var(--muted-foreground);margin:0 0 18px}.cards{display:grid;grid-template-columns:1fr 1fr;gap:14px}.card{background:var(--card);border:1px solid var(--border);border-radius:var(--radius,12px);padding:18px}.label{font-weight:600;font-size:14px}.value{font-variant-numeric:tabular-nums;font-size:31px;line-height:1.2;margin:14px 0 6px}.meta{font-size:13px;color:var(--muted-foreground)}.bar{height:10px;background:var(--secondary);border-radius:6px;margin:18px 0 8px;overflow:hidden}.fill{height:10px;background:#FA4616;border-radius:6px}.card:nth-child(2) .fill{background:#00A3E0}.control{display:flex;align-items:center;gap:14px;margin:18px 0 8px;flex-wrap:wrap}input{width:95px;padding:8px;border:1px solid var(--border);border-radius:8px;background:var(--background);color:var(--foreground);font:inherit}summary{cursor:pointer;font-weight:600;margin-top:14px}table{border-collapse:collapse;width:100%;font-size:13px;margin-top:10px}th,td{padding:7px 4px;border-bottom:1px solid var(--border);text-align:right}th:first-child,td:first-child{text-align:left}small{display:block;color:var(--muted-foreground);margin-top:12px}@media(max-width:480px){.cards{grid-template-columns:1fr}.value{font-size:28px}}
</style><h2>Cost estimat pentru 900 de cadre la 1080p</h2><p class="sub">M5 Max · Metal. Medie ponderată din șase momente, după încălzire.</p><div class="cards" id="cards"></div><label class="control">Număr de cadre <input id="frames" type="number" min="1" max="90000" value="900"><span id="duration"></span></label><small>Include pregătirea scenei, randarea, denoise și PNG. Fără compoziția 2D sau motion blur. Sesiune cu presiune RAM: circa 16,9 GB swap în proba Cycles 64; estimări conservatoare, de reverificat pe un lot continuu. Filmul complet nu a fost pornit.</small><details><summary>Timpii celor șase probe, în secunde</summary><table><thead><tr><th>Moment</th><th>Cycles 512</th><th>Cycles 64</th><th>EEVEE 128</th></tr></thead><tbody>ROWS</tbody></table></details><script>
const data=DATA;const cards=document.getElementById('cards');function update(){const n=Math.max(1,Number(document.getElementById('frames').value)||900);const max=Math.max(...data.map(x=>x.seconds));cards.innerHTML=data.map(x=>`<div class="card"><div class="label">${x.name}</div><div class="value">${(n*x.seconds/60).toFixed(1)} min</div><div class="meta">${x.seconds.toFixed(2)} s/cadru · estimare</div><div class="bar"><div class="fill" style="width:${x.seconds/max*100}%"></div></div><div class="meta">Probe: ${x.minimum.toFixed(2)}–${x.maximum.toFixed(2)} s/cadru</div></div>`).join('');document.getElementById('duration').textContent=(n/30).toFixed(1)+' s de film la 30 fps';}document.getElementById('frames').addEventListener('input',update);update();console.log('Cost model:',JSON.stringify(data));
</script></html>'''.replace('ROWS',rows).replace('DATA',json.dumps(data))
(ROOT/'qa'/'render_costs.html').write_text(html)
print('Wrote qa/render_costs.html')
